<p class="eyebrow"><?= $e($t('DELEGATED ACCESS · PRIVATE')) ?></p><h1><?= $e($t('Community team')) ?></h1><p class="notice"><?= $e($t('Give each steward their own account. Share temporary passwords privately and ask people to change them on first sign-in. Reviewers can read private records; stewards and community admins can maintain records and decide requests. These roles do not verify community authority.')) ?></p>
<?php if ($actor['is_owner']): ?><section class="card"><h2><?= $e($t('Add a community collection')) ?></h2><form data-api="/api/team" data-reload><input type="hidden" name="action" value="community"><label><?= $e($t('Collection name')) ?><input name="name" required maxlength="200"></label><button class="button"><?= $e($t('Add collection')) ?></button><p class="form-message" role="status"></p></form></section><?php endif ?>
<section class="card"><h2><?= $e($t('Add a team member')) ?></h2><form data-api="/api/team" data-reload><input type="hidden" name="action" value="account"><div class="two"><label><?= $e($t('Username')) ?><input name="username" minlength="3" maxlength="100" pattern="[a-zA-Z0-9][a-zA-Z0-9._\-]{2,99}" required autocomplete="off"></label><label><?= $e($t('Display name')) ?><input name="displayName" required maxlength="200"></label><label><?= $e($t('Email')) ?><input name="email" type="email" required maxlength="254"></label><label><?= $e($t('Temporary password (12–72 bytes)')) ?><input name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><label><?= $e($t('Community collection')) ?><select name="communityId"><?php foreach ($adminCommunities as $community): ?><option value="<?= $e($community['id']) ?>"><?= $e($community['name']) ?></option><?php endforeach ?></select></label><label><?= $e($t('Role')) ?><select name="role"><option value="STEWARD"><?= $e($t('Steward · maintain records')) ?></option><option value="REVIEWER"><?= $e($t('Reviewer · read only')) ?></option><option value="ADMIN"><?= $e($t('Community admin · records and team')) ?></option></select></label></div><button class="button"><?= $e($t('Create account')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Assign or remove community access')) ?></h2><form data-api="/api/team" data-reload><input type="hidden" name="action" value="membership"><label><?= $e($t('Account')) ?><select name="accountId"><?php foreach ($accounts as $member): ?><option value="<?= $e($member['id']) ?>"><?= $e($member['username']) ?> · <?= $e($member['display_name']) ?></option><?php endforeach ?></select></label><label><?= $e($t('Community collection')) ?><select name="communityId"><?php foreach ($adminCommunities as $community): ?><option value="<?= $e($community['id']) ?>"><?= $e($community['name']) ?></option><?php endforeach ?></select></label><label><?= $e($t('Role')) ?><select name="role"><option value="STEWARD"><?= $e($t('Steward')) ?></option><option value="REVIEWER"><?= $e($t('Reviewer')) ?></option><option value="ADMIN"><?= $e($t('Community admin')) ?></option><option value="REMOVE"><?= $e($t('Remove access')) ?></option></select></label><button class="button secondary"><?= $e($t('Update access')) ?></button><p class="form-message" role="status"></p></form></section>
<section class="card"><h2><?= $e($t('Current community access')) ?></h2><?php foreach ($memberships as $membership): ?><p><?= $e($membership['username']) ?> · <?= $e($membership['name']) ?> · <span class="badge"><?= $e($membership['role']) ?></span></p><?php endforeach ?></section>
<?php if ($actor['is_owner']): ?><section><h2><?= $e($t('Account status and recovery')) ?></h2><?php foreach ($accounts as $member): ?><article class="card"><h3><?= $e($member['display_name']) ?></h3><p><?= $e($member['username']) ?> · <?= $e($member['email']) ?> · <?= $e($t($member['active']?'Active':'Disabled')) ?></p><?php if (!$member['is_owner']): ?><form data-api="/api/team" data-reload><input type="hidden" name="action" value="active"><input type="hidden" name="accountId" value="<?= $e($member['id']) ?>"><label class="check"><input type="checkbox" name="active" <?= $member['active']?'checked':'' ?>> <?= $e($t('Account enabled')) ?></label><button class="button secondary"><?= $e($t('Save account status')) ?></button><p class="form-message" role="status"></p></form><details><summary><?= $e($t('Reset password')) ?></summary><form data-api="/api/team" data-reload><input type="hidden" name="action" value="resetPassword"><input type="hidden" name="accountId" value="<?= $e($member['id']) ?>"><label><?= $e($t('New temporary password')) ?><input type="password" name="password" minlength="12" maxlength="72" required autocomplete="new-password"></label><button class="button secondary"><?= $e($t('Reset password and end active sessions')) ?></button><p class="form-message" role="status"></p></form></details><?php else: ?><span class="badge"><?= $e($t('Site owner')) ?></span><?php endif ?></article><?php endforeach ?></section><?php endif ?>
